import 'package:flutter/widgets.dart';

import '../types/resource_type.dart';
import 'generated/app_localizations.dart';

/// The app's strings (`lib/l10n/app_pt.arb`, generated by `flutter gen-l10n`).
///
/// Falls back to Portuguese when no `MaterialApp` registered
/// [AppLocalizations.delegate], e.g. in a widget test that pumps a bare
/// widget, so every screen can read `context.l10n` unconditionally.
extension AppLocalizationsContext on BuildContext {
  AppLocalizations get l10n =>
      Localizations.of<AppLocalizations>(this, AppLocalizations) ??
      lookupAppLocalizations(const Locale('pt'));
}

/// Names of each [ResourceType]; the type itself carries no text.
extension ResourceTypeLabels on AppLocalizations {
  String resourceLabel(ResourceType type) => switch (type) {
    ResourceType.character => resourceCharacter,
    ResourceType.episode => resourceEpisode,
    ResourceType.location => resourceLocation,
  };

  String resourcePluralLabel(ResourceType type) => switch (type) {
    ResourceType.character => resourceCharacters,
    ResourceType.episode => resourceEpisodes,
    ResourceType.location => resourceLocations,
  };
}
